package integration_test
import("context";"testing";"time";"github.com/vance1852/foodsafe-traceability/internal/sampling")
func TestEmergencySampleRollback(t *testing.T){f:=newFixture(t);g:=f.createSourceGraph(t);now:=time.Now().UTC();p,err:=f.sampling.CreatePlan(context.Background(),f.supervisor,sampling.CreatePlanCommand{FacilityID:g.source.ID,StationID:g.station.ID,AssignedUserID:f.field.UserID,WindowStart:now.Add(-time.Hour),WindowEnd:now.Add(time.Hour),RequiredBottles:2,RequestID:"private-clone-31-plan"});if err!=nil{t.Fatal(err)};if err=f.sampling.PublishPlan(context.Background(),f.supervisor,p.ID,"private-clone-31-publish");err!=nil{t.Fatal(err)};if _,err=f.store.DB().Exec(`CREATE TRIGGER fail_sampling_collect_audit BEFORE INSERT ON audit_events WHEN NEW.action = 'sample.collect' BEGIN SELECT RAISE(ABORT, 'audit sink unavailable'); END`);err!=nil{t.Fatal(err)};_,err=f.sampling.Collect(context.Background(),f.field,sampling.CollectCommand{PlanID:p.ID,BottleCount:2,CollectedAt:now,RequestID:"private-clone-31-failing"});if err==nil{t.Fatal("collect unexpectedly succeeded")};var count int;if err=f.store.DB().QueryRow(`SELECT COUNT(*) FROM samples WHERE plan_id=?`,p.ID).Scan(&count);err!=nil{t.Fatal(err)};if count!=0{t.Fatalf("failed collect persisted %d samples",count)};if _,err=f.store.DB().Exec(`DROP TRIGGER fail_sampling_collect_audit`);err!=nil{t.Fatal(err)};_,err=f.sampling.Collect(context.Background(),f.field,sampling.CollectCommand{PlanID:p.ID,BottleCount:2,CollectedAt:now,RequestID:"private-clone-31-retry"});if err!=nil{t.Fatal(err)}}
